#include "fractal/retry_policy.h"
fractal_retry_decision fractal_retry_evaluate(fractal_retry_policy p,fractal_retry_failure_class f,uint64_t spent,bool fg){fractal_retry_decision d={false,0,f};uint64_t delay=p.base_delay_ticks;uint32_t i;if(p.user_forced_retry&&(f==FRACTAL_REQUIRE_USER_ACTION||f==FRACTAL_RETRY_AFTER_NETWORK_CHANGE)){d.retry=true;return d;}if((fg&&!p.foreground_allowed)||(!fg&&!p.background_allowed))return d;if(f==FRACTAL_REQUIRE_USER_ACTION||f==FRACTAL_REQUIRE_REPAIRING||f==FRACTAL_PERMANENT_INCOMPATIBILITY||f==FRACTAL_PERMANENT_REVOCATION)return d;if(spent>=p.total_retry_budget_ticks)return d;if(f==FRACTAL_RETRY_AFTER_NETWORK_CHANGE){d.retry=true;return d;}if(f==FRACTAL_RETRY_BACKOFF&&p.backoff_class==FRACTAL_BACKOFF_EXPONENTIAL){for(i=0;i<p.attempt_number&&delay<p.maximum_delay_ticks;i++){delay*=2u;if(delay>p.maximum_delay_ticks){delay=p.maximum_delay_ticks;break;}}}if(f==FRACTAL_RETRY_IMMEDIATE)delay=0;if(delay+p.jitter_bound_ticks>p.maximum_delay_ticks)delay=p.maximum_delay_ticks;else delay+=p.jitter_bound_ticks;d.retry=true;d.delay_ticks=delay;return d;}
